import javax.swing.*;import javax.swing.table.DefaultTableModel;import javax.swing.tree.DefaultMutableTreeNode;import java.awt.*;
/** Non-destructive desktop file-manager UI mockup demonstrating tree, table, tabs, menus and toolbar. */
public class FileManagerMockup extends JFrame{
 FileManagerMockup(){super("Week 5 — File Manager Mockup");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(850,520);setLocationRelativeTo(null);
 JMenuBar bar=new JMenuBar();JMenu file=new JMenu("File");for(String s:new String[]{"New folder…","Open…","Save view…","Exit"}){JMenuItem i=new JMenuItem(s);if(s.equals("Exit"))i.addActionListener(e->dispose());else i.addActionListener(e->JOptionPane.showMessageDialog(this,s+" is a mockup action; no files changed."));file.add(i);}bar.add(file);bar.add(new JMenu("Edit"));bar.add(new JMenu("Help"));setJMenuBar(bar);
 JToolBar tools=new JToolBar();for(String s:new String[]{"Back","Forward","Refresh","New folder"}){JButton b=new JButton(s);b.addActionListener(e->JOptionPane.showMessageDialog(this,"Demo only — filesystem unchanged."));tools.add(b);}add(tools,BorderLayout.NORTH);
 DefaultMutableTreeNode root=new DefaultMutableTreeNode("Workspace");DefaultMutableTreeNode projects=new DefaultMutableTreeNode("Projects");projects.add(new DefaultMutableTreeNode("RBCS7312"));projects.add(new DefaultMutableTreeNode("Java labs"));root.add(projects);root.add(new DefaultMutableTreeNode("Documents"));root.add(new DefaultMutableTreeNode("Downloads"));JTree tree=new JTree(root);JTabbedPane tabs=new JTabbedPane();String[] cols={"Name","Type","Size","Modified"};Object[][] rows={{"README.md","Markdown","3 KB","Today"},{"pom.xml","XML","2 KB","Today"},{"src","Folder","—","Yesterday"}};tabs.addTab("Details",new JScrollPane(new JTable(new DefaultTableModel(rows,cols))));tabs.addTab("Preview",new JLabel("Select an item to preview",SwingConstants.CENTER));JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(tree),tabs);split.setDividerLocation(220);add(split,BorderLayout.CENTER);add(new JLabel("  Mock filesystem · actions do not modify files"),BorderLayout.SOUTH);}
 public static void main(String[]a){SwingUtilities.invokeLater(()->new FileManagerMockup().setVisible(true));}
}
